      );

    const skillSignals =
      uniqueText([
        ...arrayify(
          focusEvaluation?.buffs
        ),
        ...arrayify(
          focusBoat?.buffs
        )
      ])
        .filter(text =>
          /全国実績|当地実績|地元|級別|選手技量|平均ST/.test(
            text
          )
        )
        .slice(0, 3);

    const abilitySignals =
      uniqueText([
        /^[AB][12]$/.test(
          className
        )
          ? `${className}級`
