      "",
      `${selectionType}｜${scoreLabel} ${displayedScore}点`,
      "※点数はAI評価であり、的中確率ではありません。",
      "",
      "【結論】",
          isWave
        ? conclusion
        : `${boatLabel(
            main.honmei
          )}を軸に、${conclusion}`,
      "",
      "【根拠】",
      abilityReason,
            "評価順　展開→コース→ST・スリット→展示・足→残し・拾い→当地・水面→選手技量→モーター",
      "",
      "【水面】",
      `${safeText(
        venue.water,
        "未取得"
      )}｜風${safeText(
        weather.windDirection,
        "-"
      )}${weather.windSpeed ?? "-"}m｜波${weather.waveHeight ?? "-"}cm`,
      "",

      buildOfficialHistorySection(
        prediction
      ),

      "",
      "ここから先で、6艇評価・AI優先候補・実戦厳選（基本5〜7点、成立展開時最大10点）を公開します。"
    ].join("\n");
  }

    function buildBoatAnalysis(
    prediction
  ) {
    const rows =
      arrayify(
        prediction
          ?.mainSheet
          ?.evaluations
      );

    if (!rows.length) {
      return "艇別評価データはありません。";
    }

    return rows
      .map(item => {
        const buffs =
          uniqueText(
            item.buffs
          )
            .slice(0, 2)
            .join("・") ||
          "補正なし";

        const debuffs =
          uniqueText(
            item.debuffs
          )
            .slice(0, 1)
            .join("・");

        const comment =
          safeText(
            firstValue([
              item.shortComment,
              item.comment,
              item.role
            ]),
            "総合評価"
          );

        const caution =
          debuffs
            ? `｜注意：${debuffs}`
            : "";

        return (
          `${boatLabel(item)}　` +
          `${Math.round(
            safeNumber(
              item.score,
              0
            )
          )}点｜` +
          `${buffs}` +
          `${caution}｜` +
          `${comment}`
        );
      })
      .join("\n");
  }

  function buildTicketGroup(
    title,
    list,
    category
  ) {
