  function buildTags(
    prediction,
    options = {}
  ) {
    const meta =
      getRaceMeta(prediction);

    const baseTags = [
      "ボートレース",
      "競艇予想",
      "ボートレース予想",
      "AI予想",
      meta.place,
      "チャッピーボートレースAI"
    ];

    return uniqueText([
      ...baseTags,
      ...arrayify(options.tags)
    ]).map(tag =>
      `#${tag.replace(/^#/, "")}`
    );
  }

    function generateArticle(prediction, options = {}) {
    if (
      !prediction ||
      typeof prediction !== "object"
    ) {
      return {
        ok: false,
        version: VERSION,
        error: "予想データがありません。"
      };
    }

    const allRaces = options.publicationPolicy === "all-races-v1";
    const rejectionReasons = [];
    const main =
      prediction?.mainSheet || {};
    const flow =
      prediction?.raceFlow || {};
    const lists =
      ticketLists(prediction);

    const practicalTickets =
      articlePracticalTickets(
        prediction, options
      );

    const honmeiNo =
      safeNumber(
        main?.honmei?.boatNo,
        0
      );

    const honmeiEvaluation =
      arrayify(
        main?.evaluations
      ).find(
        item =>
          safeNumber(
            item?.boatNo,
            0
          ) === honmeiNo
      ) ||
      main?.honmei ||
      null;

    const honmeiCourse =
      safeNumber(
        firstValue([
          honmeiEvaluation?.course,
          main?.honmei?.course,
          honmeiNo
        ]),
        0
      );

    const honmeiScore =
      safeNumber(
        honmeiEvaluation?.score,
        0
      );

    const flowTitle =
      safeText(
        flow?.title,
        ""
      );

    const flowSummary =
      safeText(
        flow?.summary,
        ""
      );

    let requiredMainCourse = 0;

    if (
      /イン逃げ本線/.test(
        flowTitle
      )
    ) {
      requiredMainCourse = 1;
    } else {
      const courseMatch =
        flowTitle.match(
          /([1-6])コース[^。]*本線/
        );

      requiredMainCourse =
        courseMatch
          ? Number(courseMatch[1])
          : 0;
    }

    if (!honmeiNo) {
      rejectionReasons.push(
        "◎本命艇を取得できません"
      );
    }

    if (
      requiredMainCourse &&
      honmeiCourse !==
        requiredMainCourse
    ) {
      rejectionReasons.push(
        `中心展開は${requiredMainCourse}コース本線ですが、◎は${honmeiNo || "-"}号艇です`
      );
    }

    if (
      !allRaces && honmeiNo &&
      honmeiScore < 72
    ) {
      rejectionReasons.push(
        `◎${honmeiNo}号艇の艇評価が${Math.round(
          honmeiScore
        )}点で、頭候補の基準を満たしていません`
      );
    }

    const honmeiComment =
      safeText(
        firstValue([
          honmeiEvaluation
            ?.shortComment,
          honmeiEvaluation
            ?.comment
        ]),
        ""
      );

    if (
      !allRaces && honmeiNo &&
      /相手・3着|押さえ候補|展開待ち|厚くは買わない|厳しい条件/.test(
        honmeiComment
      )
    ) {
      rejectionReasons.push(
        `◎${honmeiNo}号艇の艇評価が「頭候補」ではありません`
      );
    }

    const mainTickets =
      arrayify(
        lists.main
      )
        .map(item =>
          normalizeTicket(
            item,
            "本線"
          )
        )
        .filter(
          item => item.ticket
        );

    if (!mainTickets.length) {
      rejectionReasons.push(
        "本線買い目を生成できません"
      );
    } else if (
      honmeiNo &&
      mainTickets.some(
        item =>
          Number(
            item.ticket
              .split("-")[0]
          ) !== honmeiNo
      )
    ) {
      rejectionReasons.push(
        "本線買い目の1着軸が◎本命艇と一致していません"
      );
    }

    function boatsBeforeRole(
      text,
      role
    ) {
      const boats = [];
      let searchFrom = 0;

      while (
        searchFrom <
        text.length
      ) {
        const roleIndex =
          text.indexOf(
            role,
            searchFrom
          );

        if (roleIndex < 0) {
          break;
        }

        const prefix =
          text.slice(
            0,
            roleIndex
          );

        const matches = [
          ...prefix.matchAll(
            /([1-6])号艇/g
          )
        ];

        const nearest =
          matches[
            matches.length - 1
          ];

        if (nearest) {
          boats.push(
            Number(nearest[1])
          );
        }

        searchFrom =
          roleIndex +
          role.length;
      }

      return uniqueText(
        boats
      ).map(Number);
    }

    function contradictoryRoleBoats(
      text
    ) {
      const sentences =
        safeText(text, "")
          .split(/[。！？\n]+/)
          .map(sentence =>
            sentence.trim()
          )
          .filter(Boolean);

      return uniqueText(
        sentences.flatMap(sentence => {
          const holdBoats =
            boatsBeforeRole(
              sentence,
              "残し"
            );
          const pickupBoats =
            boatsBeforeRole(
              sentence,
              "拾い"
            );

          return holdBoats.filter(
            boatNo =>
              pickupBoats.includes(
                boatNo
              )
          );
        })
      ).map(Number);
    }

    const contradictoryRoles =
      contradictoryRoleBoats(
        flowSummary
      );

    if (
      contradictoryRoles.length
    ) {
      rejectionReasons.push(
        `${contradictoryRoles.join(
          "・"
        )}号艇が同一展開内で「残し」と「拾い」に重複しています`
      );
    }

    if (
      prediction
        ?.dataQuality
        ?.boatIdentity
        ?.valid === false
    ) {
      const identityReason =
        root.ChappyBoatIdentity
          ?.reasonText(
            prediction
              .dataQuality
              .boatIdentity
          ) ||
        "1〜6号艇を一意に確認できません";
      rejectionReasons.push(
        `艇番不整合：${identityReason}`
      );
    }

    if (
      !allRaces && String(
        prediction
          ?.dataQuality
          ?.level || ""
      ) === "低"
    ) {
      rejectionReasons.push(
        "予想データの品質判定が低です"
      );
    }

    if (
      !practicalTickets.length
    ) {
      rejectionReasons.push(
        "実戦厳選買い目を生成できません"
      );
    }

    if (
      rejectionReasons.length
    ) {
      return {
        ok: false,
        publishable: false,
        version: VERSION,
        error:
          `販売見送り：` +
          uniqueText(
            rejectionReasons
          ).join("／"),
        rejectionReasons:
          uniqueText(
            rejectionReasons
          )
      };
    }

    const title =
      buildTitle(
        prediction,
        options
      );

    const freeText =
      buildFreeSection(
        prediction,
        options
      );

    const paidText =
      buildPaidSection(
        prediction, practicalTickets
      );

    const tags =
      buildTags(
        prediction,
        options
      );

    const notice =
      options.notice === false
        ? ""
        : "※舟券の購入は自己責任で、無理のない範囲でお楽しみください。";

    const fullText = [
      freeText,
      PAYWALL_MARKER,
      paidText,
      notice,
      tags.join(" ")
    ]
      .filter(Boolean)
      .join("\n\n");

    const article = {
      ok: true,
      publishable: true,
      version: VERSION,
      title,
      freeText,
      paidText,
      paywallMarker:
        PAYWALL_MARKER,
      fullText,
      tags,
      practicalTickets,
      meta:
        getRaceMeta(
          prediction
        )
    };
    if (allRaces) return allRaceArticle(compactArticle(article, prediction), prediction);
    return options.format === "detailed" ? article : compactArticle(article, prediction);
  }

  function allRaceArticle(article, prediction) {
    const meta = getRaceMeta(prediction);
    const disclosure = "作成時点の取得済み情報による参考予想です。展示・気象・オッズ等の追加情報で評価が変わる場合があります。";
    const focus = briefReason(article.rangeSummary || "")
      .split(/(?<=[。！？])/)[0].trim();
    const practicalCount = article.practicalTickets.length;
    const freeText = [
      `🚤 ${formatDate(meta.date)} ${meta.place}${meta.raceNo}R｜${formatDeadlineLabel(meta.deadline)}`,
      focus ? `展開の焦点：${focus}` : "",
      "本命・押さえ・万舟を、展開の狙いとフォーメーションで掲載しています。",
      `実戦厳選は${practicalCount}点です。各区分の候補と重複するため、全部を合算して買う案内ではありません。`,
      disclosure
    ].filter(Boolean).join("\n\n");
    const fullText = [freeText, PAYWALL_MARKER, article.paidText,
